package com.skyjjgw.independent.ski

import android.content.Context
import org.json.JSONObject
import java.io.File
import java.io.RandomAccessFile
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.Executors

/** Native Android shell is the real app UID, independent of ADB and Linux. */
object CloudAndroidRuntime {
    private val pool=Executors.newCachedThreadPool()
    private val processes=ConcurrentHashMap<String,Process>()
    private val launching=ConcurrentHashMap.newKeySet<String>()
    private val cancelled=ConcurrentHashMap.newKeySet<String>()
    private val paused=ConcurrentHashMap.newKeySet<String>()
    private val lock=Any()
    private val contexts=ConcurrentHashMap<String,Context>()
    init{java.util.concurrent.Executors.newSingleThreadScheduledExecutor().scheduleWithFixedDelay({contexts.values.forEach{context->runCatching{pump(context)}}},1,1,java.util.concurrent.TimeUnit.SECONDS)}
    fun restore(context:Context){contexts[context.packageName]=context.applicationContext;all(context).forEach{refresh(context,it)};pump(context)}
    private fun base(context:Context)=File(context.filesDir,"cloud-android-jobs").apply{mkdirs()}
    private fun folder(context:Context,id:String):File{require(Regex("android_[a-f0-9]{32}").matches(id));return File(base(context),id)}
    private fun record(context:Context,id:String)=synchronized(lock){JSONObject(File(folder(context,id),"record.json").readText())}
    private fun save(context:Context,r:JSONObject)=synchronized(lock){val file=File(folder(context,r.getString("id")),"record.json");val tmp=File(file.parentFile,"record.tmp");tmp.writeText(r.toString());check(tmp.renameTo(file))}
    private fun update(context:Context,id:String,values:Map<String,Any?>):JSONObject=synchronized(lock){val r=record(context,id);values.forEach{(key,value)->r.put(key,value)};save(context,r);r}
    private fun all(context:Context)=base(context).listFiles().orEmpty().mapNotNull{runCatching{record(context,it.name)}.getOrNull()}
    private fun owned(context:Context,id:String,owner:String)=record(context,id).also{require(it.getString("owner")==owner){"程序不属于本会话。"}}
    private fun scope(r:JSONObject)="${r.getString("owner")}:${r.getString("taskId")}"
    private fun state(pid:Int):Char?=runCatching{File("/proc/$pid/stat").readText().substringAfterLast(") ").first()}.getOrNull()
    private fun contains(bytes:ByteArray,needle:ByteArray):Boolean{outer@for(at in 0..bytes.size-needle.size){for(i in needle.indices)if(bytes[at+i]!=needle[i])continue@outer;return true};return false}
    private fun members(r:JSONObject):List<Int>{val token="SKIVU_ANDROID_JOB=${r.getString("token")}\u0000".replace("\\u0000","\u0000").toByteArray();return File("/proc").listFiles().orEmpty().mapNotNull{dir->val pid=dir.name.toIntOrNull()?:return@mapNotNull null;if(state(pid) in setOf(null,'Z'))return@mapNotNull null;runCatching{if(contains(File(dir,"environ").readBytes(),token))pid else null}.getOrNull()}}
    private fun signal(r:JSONObject,signal:Int){for(pid in members(r))runCatching{android.os.Process.sendSignal(pid,signal)}}
    private fun refresh(context:Context,r:JSONObject):JSONObject{val id=r.getString("id");if(r.optString("state") in setOf("starting","running","stopping","paused","paused_storage")&&!launching.contains(id)&&!processes.containsKey(id)&&members(r).isEmpty())return update(context,id,mapOf("state" to "unknown","reason" to "原进程和输入通道已中断，工作文件及日志保留；先核对，不重放命令。"));return r}
    private fun parts(file:File):List<Triple<File,Long,Long>>{val main=if(file.isFile)file.length()else 0L;val result=mutableListOf<Triple<File,Long,Long>>();if(file.isFile)result.add(Triple(file,0,main));val pending=File(file.path+".pending");if(pending.isFile){val metadata=File(pending.path+".meta.json");val start=if(metadata.isFile)(main-JSONObject(metadata.readText()).getLong("offset")).coerceAtLeast(0).coerceAtMost(pending.length())else 0L;result.add(Triple(pending,start,pending.length()-start))};return result}
    private fun page(file:File,offset:Long,length:Int):Map<String,Any?> = synchronized(lock){require(offset>=0&&length>0);val parts=parts(file);val size=parts.sumOf{it.third};val wanted=minOf(maxOf(4,length),1024*1024);val buffer=ByteArray(minOf(wanted.toLong()+3,(size-offset).coerceAtLeast(0)).toInt());var logical=0L;var n=0;for((part,start,total) in parts){if(offset+n>=logical+total){logical+=total;continue};RandomAccessFile(part,"r").use{input->var at=(offset+n-logical).coerceAtLeast(0);input.seek(start+at);while(n<buffer.size&&at<total){val got=input.read(buffer,n,minOf(buffer.size-n,(total-at).toInt()));if(got<0)break;n+=got;at+=got}};logical+=total;if(n==buffer.size)break};var end=minOf(wanted,n);if(offset+end<size)while(end>0&&end<n&&(buffer[end].toInt() and 0xc0)==0x80)end--;mapOf("text" to String(buffer,0,end,Charsets.UTF_8),"offset" to offset+end,"nextOffset" to offset+end,"bytes" to size,"complete" to (offset+end>=size))}
    private fun spool(context:Context,id:String,input:java.io.InputStream,name:String){val r=record(context,id);val dir=folder(context,id);val log=File(dir,name);val pending=File(log.path+".pending");val meta=File(pending.path+".meta.json");input.use{source->log.outputStream().use{dest->val buffer=ByteArray(65536);while(true){val n=source.read(buffer);if(n<0)break;var offset=0;while(offset<n){val before=dest.channel.position();try{synchronized(lock){dest.write(buffer,offset,n-offset);dest.flush();offset=n;meta.delete();pending.delete()}}catch(error:java.io.IOException){offset+=(dest.channel.position()-before).coerceIn(0,(n-offset).toLong()).toInt();signal(r,android.system.OsConstants.SIGSTOP);File(dir,"reserve").delete();synchronized(lock){pending.writeBytes(buffer.copyOfRange(offset,n));meta.writeText(JSONObject(mapOf("offset" to dest.channel.position(),"bytes" to n-offset)).toString())};update(context,id,mapOf("state" to if(record(context,id).optBoolean("stopRequested"))"stopping_output"else"paused_storage","reason" to error.toString(),"outputComplete" to false));while(android.os.StatFs(dir.path).availableBytes<n-offset+65536)Thread.sleep(500)}};val current=record(context,id);if(current.optString("state")=="paused_storage"&&listOf("stdout.pending","stderr.pending").none{File(dir,it).exists()}&&scope(r) !in paused&&scope(r) !in cancelled){signal(r,android.system.OsConstants.SIGCONT);update(context,id,mapOf("state" to "running"))}}}}}
    private fun export(context:Context,r:JSONObject,args:Map<String,Any?>,owner:String,task:String,request:String):Map<String,Any?>{
        val stream=args["stream"]?.toString()?:"stdout";require(stream in setOf("stdout","stderr"));val content="content_"+TaskDatabase.digest("$owner:$request:export").take(32);val directory=File(context.filesDir,"cloud-home/cloud/content").apply{mkdirs()};val data=File(directory,"$content.bin");val metadata=File(directory,"$content.json");val signature=TaskDatabase.digest(JSONObject(args.toSortedMap()).toString())
        if(!metadata.isFile){val temp=File(directory,"$content.tmp");val snapshots=synchronized(lock){parts(File(folder(context,r.getString("id")),stream)).map{(file,start,total)->Triple(file.inputStream().apply{channel.position(start)},total,file.name)}};val digest=java.security.MessageDigest.getInstance("SHA-256");var bytes=0L
            try{temp.outputStream().use{out->val buffer=ByteArray(65536);for((input,total,name) in snapshots){var left=total;while(left>0){CloudOperations.checkCurrent();val n=input.read(buffer,0,minOf(left,buffer.size.toLong()).toInt());require(n>0){"日志快照读取中断。"};out.write(buffer,0,n);digest.update(buffer,0,n);left-=n;bytes+=n;CloudOperations.report(name,bytes,null)}};out.fd.sync()}}finally{snapshots.forEach{it.first.close()}}
            check(temp.renameTo(data));val tempMeta=File(metadata.path+".tmp");tempMeta.writeText(JSONObject(mapOf("id" to content,"owner" to owner,"complete" to true,"bytes" to bytes,"sha256" to digest.digest().joinToString(""){"%02x".format(it)},"sourceSignature" to signature)).toString());check(tempMeta.renameTo(metadata))
        };require(JSONObject(metadata.readText()).getString("sourceSignature")==signature){"原导出参数不同，未覆盖原结果。"}
        var project=args["projectId"] as? String?:r.optString("exportProjectId").takeIf{it.startsWith("project_")}
        if(project==null){val reply=CloudRuntime.invoke(context,"coding.projects.create",mapOf("name" to "Android 程序日志"),owner,task,"export_project_"+TaskDatabase.digest(request).take(40));if(reply["outcome"]!="verified")return reply;project=(reply["value"] as Map<*,*>)["id"] as String;update(context,r.getString("id"),mapOf("exportProjectId" to project))}
        val path=args["path"] as? String?:"logs/${r.getString("id")}.$stream.log";val parameters=mutableMapOf<String,Any?>("projectId" to project,"path" to path,"contentId" to content);if(args["expectedSha256"]!=null)parameters["expectedSha256"]=args["expectedSha256"]
        val reply=CloudRuntime.invoke(context,"coding.files.write",parameters,owner,task,"android_export_"+TaskDatabase.digest(request).take(40));return if(reply["outcome"]=="verified")reply+mapOf("value" to (reply["value"] as Map<*,*>)+mapOf("projectId" to project))else reply
    }
    private fun view(context:Context,raw:JSONObject,args:Map<String,Any?> = emptyMap()):Map<String,Any?>{val r=refresh(context,record(context,raw.getString("id")));val dir=folder(context,r.getString("id"));@Suppress("UNCHECKED_CAST") val data=plain(r) as Map<String,Any?>;return (data-setOf("token"))+mapOf("stdout" to page(File(dir,"stdout"),(args["stdoutOffset"] as? Number)?.toLong()?:0,(args["length"] as? Number)?.toInt()?:48000),"stderr" to page(File(dir,"stderr"),(args["stderrOffset"] as? Number)?.toLong()?:0,(args["length"] as? Number)?.toInt()?:48000),"inputAvailable" to processes.containsKey(r.getString("id")),"outputTruncated" to false,"androidUid" to android.os.Process.myUid(),"privilege" to "android_app_uid")}
    fun list(context:Context,owner:String)=all(context).filter{it.optString("owner")==owner}.map{view(context,it)}
    private fun pump(context:Context){synchronized(lock){val queued=all(context).filter{it.optString("state")=="queued"};val memory=android.app.ActivityManager.MemoryInfo();context.getSystemService(android.app.ActivityManager::class.java).getMemoryInfo(memory);if(memory.lowMemory)return
        var active=all(context).filter{it.optString("state") in setOf("starting","running","paused","paused_storage","stopping","stopping_output")}.toMutableList()
        val configured=context.getSharedPreferences("cloud_execution",0).getInt("maxAndroidJobs",0);val parallel=if(configured>0)configured else minOf(Runtime.getRuntime().availableProcessors(),(memory.availMem/(64*1024*1024)).coerceAtLeast(1).toInt())
        for(r in queued){if(scope(r) in cancelled||CloudOperations.wasStopped(context,r.getString("owner"),r.getString("taskId"))){update(context,r.getString("id"),mapOf("state" to "stopped"));continue};if(scope(r) in paused)continue;if(active.size>=parallel)break;if(!r.optBoolean("readOnly")&&active.any{it.optString("cwd")==r.optString("cwd")&&!it.optBoolean("readOnly")})continue;launching.add(r.getString("id"));update(context,r.getString("id"),mapOf("state" to "starting"));active.add(r);pool.execute{run(context,r.getString("id"))}}
    }}
    fun start(context:Context,args:Map<String,Any?>,owner:String,task:String,request:String):Map<String,Any?>{contexts[context.packageName]=context.applicationContext;val command=args["command"] as? String?:error("缺少命令。");require(command.isNotBlank()&&!command.contains('\u0000'));val timeout=(args["timeoutMs"] as? Number)?.toLong()?:0;require(timeout>=0)
        val r=synchronized(lock){all(context).firstOrNull{it.optString("owner")==owner&&it.optString("requestId")==request}?.also{require(it.getString("commandHash")==TaskDatabase.digest(command))}?:run{require("$owner:$task" !in cancelled){"任务已停止。"};val id="android_"+UUID.randomUUID().toString().replace("-","");val dir=folder(context,id).apply{mkdirs()};val project=args["projectId"] as? String;val cwd=if(project!=null){require(Regex("project_[a-zA-Z0-9_-]+").matches(project));val root=File(context.filesDir,"cloud-projects/$project").canonicalFile;require(root.isDirectory);val relative=args["cwd"]?.toString()?:".";require(!relative.startsWith('/')&&!relative.split('/').contains(".."));File(root,relative).canonicalFile.also{require(it==root||it.path.startsWith(root.path+"/"))}}else File(context.filesDir,"cloud-android-work").apply{mkdirs()};File(dir,"command.sh").writeText(command+"\n");JSONObject(mapOf("id" to id,"owner" to owner,"taskId" to task,"requestId" to request,"projectId" to project,"cwd" to cwd.path,"commandHash" to TaskDatabase.digest(command),"command" to command,"token" to UUID.randomUUID().toString(),"state" to "queued","createdAt" to System.currentTimeMillis(),"timeoutMs" to timeout,"readOnly" to (args["readOnly"]==true))).also{save(context,it)}}}
        pump(context);return view(context,r,args)
    }
    private fun run(context:Context,id:String){val r=record(context,id);val dir=folder(context,id);val reserve=File(dir,"reserve");try{reserve.writeBytes(ByteArray(256*1024))}catch(_:Exception){}
        try{if(r.optBoolean("stopRequested")||scope(r) in cancelled||CloudOperations.wasStopped(context,r.getString("owner"),r.getString("taskId"))){update(context,id,mapOf("state" to "stopped"));return};val builder=ProcessBuilder("/system/bin/sh",File(dir,"command.sh").path).directory(File(r.getString("cwd")));builder.environment()["SKIVU_ANDROID_JOB"]=r.getString("token");builder.environment()["HOME"]=File(context.filesDir,"cloud-home").apply{mkdirs()}.path;val process=builder.start();processes[id]=process;launching.remove(id);update(context,id,mapOf("state" to "running","outputComplete" to false));if(scope(r) in cancelled||record(context,id).optBoolean("stopRequested"))stop(context,r)
            val output=listOf(process.inputStream to "stdout",process.errorStream to "stderr").map{(input,name)->java.util.concurrent.CompletableFuture.runAsync({spool(context,id,input,name)},pool)}
            val began=android.os.SystemClock.elapsedRealtime();val timeout=r.optLong("timeoutMs");while(true){try{process.exitValue();break}catch(_:IllegalThreadStateException){};if(timeout>0&&android.os.SystemClock.elapsedRealtime()-began>=timeout){update(context,id,mapOf("timedOut" to true,"limitSource" to "user"));stop(context,r)};Thread.sleep(100)}
            output.forEach{it.get()};update(context,id,mapOf("exitCode" to process.exitValue(),"state" to if(scope(r) in cancelled||record(context,id).optBoolean("stopRequested"))"stopped"else"exited","outputComplete" to true,"finishedAt" to System.currentTimeMillis()))
        }catch(error:Exception){update(context,id,mapOf("state" to "unknown","error" to error.toString(),"outputComplete" to false))}finally{launching.remove(id);processes.remove(id);reserve.delete();pump(context)}
    }
    private fun stop(context:Context,r:JSONObject):Map<String,Any?>{val id=r.getString("id");val current=record(context,id);if(current.optString("state") in setOf("queued","paused_queue")){update(context,id,mapOf("state" to "stopped","stopRequested" to true));return view(context,current)};update(context,id,mapOf("state" to "stopping","stopRequested" to true));signal(r,android.system.OsConstants.SIGCONT);signal(r,android.system.OsConstants.SIGTERM);processes[id]?.destroy();for(i in 0..15){if(members(r).isEmpty())break;Thread.sleep(100)};if(members(r).isNotEmpty()){signal(r,android.system.OsConstants.SIGKILL);processes[id]?.destroyForcibly()};for(i in 0..20){if(members(r).isEmpty())break;Thread.sleep(100)};for(i in 0..20){if(!processes.containsKey(id))break;Thread.sleep(50)};return view(context,update(context,id,mapOf("state" to if(members(r).isNotEmpty())"unknown"else if(processes.containsKey(id))"stopping_output"else"stopped")))}
    private fun control(context:Context,r:JSONObject,pause:Boolean):Map<String,Any?>{val id=r.getString("id");if(r.optString("state") in setOf("queued","paused_queue"))return view(context,update(context,id,mapOf("state" to if(pause)"paused_queue"else"queued")));val members=members(r);require(members.isNotEmpty()){"原进程不在，未重新执行。"};signal(r,if(pause)android.system.OsConstants.SIGSTOP else android.system.OsConstants.SIGCONT);var verified=false;for(i in 0..20){verified=members.all{val state=state(it);if(pause)state in setOf('T','t',null,'Z')else state !in setOf('T','t')};if(verified)break;Thread.sleep(50)};return view(context,update(context,id,mapOf("state" to if(!verified)"unknown"else if(pause)"paused"else"running")))}
    fun taskControl(context:Context,owner:String,task:String,action:String):Map<String,Any?>{val key="$owner:$task";if(action=="cancel"){CloudOperations.cancel(context,owner,task);cancelled.add(key)};if(action=="pause")paused.add(key);if(action=="resume")paused.remove(key);val jobs=all(context).filter{it.optString("owner")==owner&&it.optString("taskId")==task&&it.optString("state") in setOf("queued","paused_queue","starting","running","paused","stopping","stopping_output","paused_storage")}.map{if(action=="cancel")stop(context,it)else control(context,it,action=="pause")};pump(context);return mapOf("jobs" to jobs,"stopped" to jobs.all{it["state"] in setOf("stopped","exited")},"state" to if(jobs.any{it["state"] in setOf("unknown","stopping_output")})"unknown"else action)}
    fun invoke(context:Context,tool:String,args:Map<String,Any?>,owner:String,request:String,task:String?=null):Any?{val r=owned(context,args["jobId"] as String,owner);return when(tool){
        "coding.jobs.export"->export(context,r,args,owner,task?:r.getString("taskId"),request)
        "coding.jobs.stop"->stop(context,r)
        "coding.jobs.pause","coding.jobs.resume"->control(context,r,tool.endsWith("pause"))
        "coding.jobs.input"->{val process=processes[r.getString("id")]?:error("原输入通道不可用，未重复启动。");val receipt=File(folder(context,r.getString("id")),"input-${TaskDatabase.digest(request)}.json");val hash=TaskDatabase.digest((args["text"] as String)+":"+(args["end"]==true));synchronized(lock){if(receipt.exists()){val old=JSONObject(receipt.readText());require(old.getString("hash")==hash);check(old.getString("state")=="accepted"){"原输入回执未知，未重复输入。"}}else{receipt.writeText(JSONObject(mapOf("hash" to hash,"state" to "prepared")).toString());process.outputStream.write((args["text"] as String).toByteArray());process.outputStream.flush();if(args["end"]==true)process.outputStream.close();receipt.writeText(JSONObject(mapOf("hash" to hash,"state" to "accepted")).toString())}};mapOf("jobId" to r.getString("id"),"inputAccepted" to true)}
        "coding.jobs.wait"->{while(refresh(context,record(context,r.getString("id"))).getString("state") in setOf("running","queued","starting")){pump(context);Thread.sleep(300)};view(context,r,args)}
        "coding.jobs.read"->view(context,r,args)
        "coding.jobs.search"->{val query=args["query"] as String;require(query.isNotEmpty());val offset=(args["cursor"] as? String)?.toLong()?:0L;val count=((args["pageSize"] as? Number)?.toInt()?:100).coerceIn(1,1000);var total=0L;val items=mutableListOf<Map<String,Any?>>();for(name in listOf("stdout","stderr")){val file=File(folder(context,r.getString("id")),name);if(file.isFile)file.bufferedReader().use{reader->var line=0L;reader.forEachLine{text->line++;if(text.contains(query)){if(total>=offset&&items.size<count)items+=mapOf("stream" to name,"line" to line,"text" to text);total++}}}};mapOf("items" to items,"total" to total,"nextCursor" to if(offset+items.size<total)(offset+items.size).toString()else null,"complete" to (offset+items.size>=total),"snapshot" to false)}
        else->error("Android程序接口不存在。")
    }}
}
